// ProfilePage.js
import React, { useState, useEffect } from 'react';
import { useLocation } from 'react-router-dom';
import styles from './ProfilePage.module.css';

const ProfilePage = () => {
    const [userData, setUserData] = useState({
        email: 'example@example.com',
        username: 'username123',
        name: 'John',
        surname: 'Doe',
        wins: 10,
        loses: 5,
        games: 15,
        winRatio: 0.67,
        status: 1,
        activeGame: 'Game XYZ'
    });

    const location = useLocation();

    useEffect(() => {
        const searchParams = new URLSearchParams(location.search);
        const userId = searchParams.get('userId');
        fetchUserData(userId);
    }, [location]);

    const fetchUserData = (userId) => {
        // Simulated API call
        setTimeout(() => {
            setUserData({
                email: 'example@example.com',
                username: 'username123',
                name: 'John',
                surname: 'Doe',
                wins: 10,
                loses: 5,
                games: 15,
                winRatio: 0.67,
                status: 1,
                activeGame: 'Game XYZ'
            });
        }, 1000);
    };

    const handlePasswordReset = () => {
        alert('Password reset functionality will be implemented here.');
    };

    return (
        <div className={styles.profilePage}>
            <div className={styles.profileCard}>
                <h2 className={styles.title}>Profile Information</h2>
                <div className={styles.personalData}>
                    {Object.entries(userData).map(([key, value]) => (
                        key !== 'status' && key !== 'activeGame' && (
                            <div key={key} className={styles.dataItem}>
                                <strong>{key.charAt(0).toUpperCase() + key.slice(1)}:</strong> {value}
                            </div>
                        )
                    ))}
                </div>
                <div className={styles.actions}>
                    <button onClick={handlePasswordReset} className={styles.resetButton}>Reset Password</button>
                    {userData.status === 2 && (
                        <div className={styles.activeGame}>
                            <strong>Active Game:</strong> {userData.activeGame}
                        </div>
                    )}
                    {userData.status === 1 && (
                        <div className={styles.status1}>
                            <strong>Status 1 Section:</strong> Content for Status 1
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
};

export default ProfilePage;
